-	}
-	if err := db.QueryRowContext(ctx, `SELECT EXISTS(SELECT 1 FROM goose_db_version WHERE version_id=55) OR EXISTS(SELECT 1 FROM posse_migration_checksums WHERE version=55)`).Scan(&destination); err != nil {
