120: func schemaDifference(want, got []string) string {
121: 	wantSet, gotSet := map[string]bool{}, map[string]bool{}
122: 	for _, statement := range want {
123: 		wantSet[statement] = true
124: 	}
125: 	for _, statement := range got {
126: 		gotSet[statement] = true
127: 	}
128: 	var differences []string
129: 	for statement := range wantSet {
130: 		if !gotSet[statement] {
131: 			differences = append(differences, "missing: "+statement)
132: 		}
133: 	}
134: 	for statement := range gotSet {
135: 		if !wantSet[statement] {
136: 			differences = append(differences, "extra: "+statement)
137: 		}
138: 	}
139: 	sort.Strings(differences)
140: 	return strings.Join(differences, "\n")
141: }
