43: func loadEmbeddedMigrations() ([]migrationSource, error) {
44: 	var sources []migrationSource
45: 	for _, dir := range []string{"upgrades", "migrations"} {
46: 		entries, err := fs.ReadDir(migrationFiles, dir)
47: 		if err != nil {
48: 			return nil, err
49: 		}
50: 		for _, entry := range entries {
51: 			name := entry.Name()
52: 			if !strings.HasSuffix(name, ".sql") {
53: 				continue
54: 			}
55: 			prefix, _, _ := strings.Cut(name, "_")
56: 			version, err := strconv.ParseInt(prefix, 10, 64)
57: 			if err != nil {
58: 				return nil, fmt.Errorf("migration %s has no version prefix", name)
59: 			}
60: 			data, err := fs.ReadFile(migrationFiles, path.Join(dir, name))
61: 			if err != nil {
62: 				return nil, err
63: 			}
64: 			sum := sha256.Sum256(data)
65: 			sources = append(sources, migrationSource{version: version, checksum: hex.EncodeToString(sum[:])})
66: 		}
67: 	}
68: 	sort.Slice(sources, func(i, j int) bool { return sources[i].version < sources[j].version })
69: 	return sources, nil
