122: run_unit_stress() {
123:   tests=$1
124:   unit_budget=${POSSE_STRESS_UNIT_BUDGET:-600}
125:   started=$(date +%s)
126:   printf '%s\n' "$tests" | awk '{ print $2, $3 }' | LC_ALL=C sort -u |
127:     while read -r tags pkg; do
128:       pattern=$(printf '%s\n' "$tests" | awk -v tags="$tags" -v pkg="$pkg" '$2 == tags && $3 == pkg { if (n++) printf "|"; printf "%s", $4 }')
129:       run=1
130:       while [ "$run" -le "$count" ]; do
131:         elapsed=$(($(date +%s) - started))
132:         if [ "$elapsed" -ge "$unit_budget" ]; then
133:           printf 'Stress budget exhausted after %d seconds; %s reached %d of %d repetitions.\n' "$elapsed" "$pkg" "$((run - 1))" "$count"
134:           if [ -n "${GITHUB_STEP_SUMMARY:-}" ]; then
135:             printf 'Stress budget exhausted after %d seconds; changed unit tests did not complete all %d repetitions.\n' "$elapsed" "$count" >> "$GITHUB_STEP_SUMMARY"
136:           fi
137:           exit 0
138:         fi
139:         remaining=$((unit_budget - elapsed))
140:         run_timeout=${timeout}
141:         case "$timeout" in *m) configured_minutes=${timeout%m}; configured_seconds=$((configured_minutes * 60)) ;; *s) configured_seconds=${timeout%s} ;; *) configured_seconds=$unit_budget ;; esac
142:         if [ "$configured_seconds" -gt "$remaining" ]; then
143:           if [ "$remaining" -lt 60 ]; then
144:             run_timeout=60s
145:           else
146:             run_timeout="${remaining}s"
147:           fi
148:         fi
149:         flags="-race -count=1 -timeout=$run_timeout -v"
150:         [ "$tags" = - ] || flags="-tags=$tags $flags"
151:         printf 'Stress run %d/%d for %s: %s\n' "$run" "$count" "$pkg" "$pattern"
152:         # shellcheck disable=SC2086 # flags hold no spaces inside a word
153:         if [ "$pkg" = internal/app ]; then
154:           systemd-run --user --scope -p TasksMax=400 -p MemoryMax=6G go test $flags "./$pkg" -run "^($pattern)\$" || exit 1
155:         else
156:           go test $flags "./$pkg" -run "^($pattern)\$" || exit 1
157:         fi
158:         run=$((run + 1))
159:       done
160:     done
161: }
